window.AUTH=window.AUTH||{};window.AUTH["88-1105"]={"d":"88-1105","id":"1989/88-1105","n":"Guidry v. Sheet Metal Workers National Pension Fund","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"","url":"https://www.justice.gov/osg/media/212451/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/curtis-guidry-petitioner-v-sheet-metal-workers-national-pension-fund-et-al-1","toa":false,"n":51}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep493/usrep493365/usrep493365.pdf","tr":false,"items":[{"t":"case","label":"AT&T v. Merry","cite":"592 F.2d 118","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/592/118/","by":{"0":""}},{"t":"case","label":"Ellis National Bank v. Irving Trust Co.","cite":"786 F.2d 466","y":1986,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/786/466/","op":2,"by":{"0":""}},{"t":"case","label":"St. Paul Fire & Marine Ins. Co. v. Cox","cite":"752 F.2d 550","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/752/550/","op":2,"by":{"0":""}},{"t":"case","label":"District of Columbia and Eleventh Circuits in Crawford v. La Boucherie Bernard Ltd.","cite":"815 F.2d 117","url":"https://www.courtlistener.com/c/F.2d/815/117/","op":2,"sum":"Recognizing exception to anti-alienation provision when trustee defrauds the pension plan.","sumSrc":"opinion","by":{"0":""}},{"t":"case","label":"Second Circuits in United Metal Products Corp. v. National Bank","cite":"811 F.2d 297","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/811/297/","op":1,"by":{"0":""}},{"t":"case","label":"Mackey v. Lanier Collection Agency & Service, Inc.","cite":"108 S. Ct. 2182","y":1988,"id":"1987/86-1387","sc":1,"op":2,"sum":"After respondent collection agency obtained money judgments against participants in an \"employee welfare benefit plan\" covered by the Employee Retirement Income Security Act of 1974 (ERISA), its request to garnish the debtors' plan benefits was granted by a Georgia trial court. The State Court of Appeals reversed, holding that Ga. Code Ann. § 18-4-22.1 (1982), barring the garnishment of \"[flunds or benefits of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Alessi v. Raybestos-Manhattan, Inc.","cite":"451 U.S. 504","y":1981,"id":"1980/79-1943","sc":1,"sum":"In two suits initiated in New Jersey state court, retired employees who had received workers' compensation awards subsequent to retirement challenged the validity of provisions in their employers' pension plans reducing a retiree's pension benefits by an amount equal to a workers' compensation award for which the retiree is eligible. These private pension plans are subject to federal regulation under the Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Fremont v. McGraw-Edison Co.","cite":"606 F.2d 752","y":1979,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/606/752/","op":1,"by":{"0":""}},{"t":"case","label":"Winer v. Edison Bros. Stores Pension Plan","cite":"593 F.2d 307","y":1979,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/593/307/","op":1,"by":{"0":""}},{"t":"case","label":"Vink v. SHV N. Am. Holding Corp.","cite":"549 F. Supp. 268","y":1982,"court":"S.D. N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./549/268/","op":1,"by":{"0":""}},{"t":"case","label":"NLRB v. Amax Coal Co.","cite":"453 U.S. 322","y":1981,"id":"1980/80-289","sc":1,"sum":"Employer-selected trustees of a § 302 (c) (5) trust fund are not \"representatives\" of the employer \"for the purposes of collective bargaining or the adjustment of grievances\" within the meaning of § 8 (b) (1) (B). Pp. 328-338. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Crausman v. Curtis-Wright Corp.","cite":"676 F. Supp. 1302","y":1988,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./676/1302/","by":{"0":""}},{"t":"case","label":"Shaw v. Delta Air Lines, Inc.","cite":"463 U.S. 85","y":1983,"id":"1982/81-1578","sc":1,"sum":"New York's Human Rights Law forbids discrimination in employee benefit plans on the basis of pregnancy, and its Disability Benefits Law requires employers to pay sick-leave benefits to employees unable to work because of pregnancy. Section 514(a) of the federal Employee Retirement Income Security Act of 1974 (ERISA) provides, with enumerated exceptions, that ERISA shall supersede \"any and all state laws insofar as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Morrissey v. Curran","cite":"650 F.2d 1267","y":1981,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/650/1267/","by":{"0":""}},{"t":"case","label":"Int'l Ass'n of Bridge Workers v. Norris","cite":"383 F.2d 735","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/383/735/","by":{"0":""}},{"t":"case","label":"Highway Truck Drivers & Helpers v. Cohen","cite":"334 F.2d 378","url":"https://www.courtlistener.com/c/F.2d/334/378/","by":{"0":""}},{"t":"case","label":"United Mine Workers of America v. Boyle","cite":"567 F.2d 112","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/567/112/","by":{"0":""}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"op":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Samples v. Samples","cite":"414 F. Supp. 773","y":1976,"court":"W.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp./414/773/","by":{"0":""}},{"t":"case","label":"Donovan v. Hamilton County Municipal Court","cite":"580 F. Supp. 554","y":1984,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./580/554/","by":{"0":""}},{"t":"case","label":"Tenneco, Inc. v. First Virginia Bank","cite":"698 F.2d 688","y":1983,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/698/688/","op":1,"by":{"0":""}},{"t":"case","label":"General Motors Corp. v. Buha","cite":"623 F.2d 455","y":1980,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/623/455/","by":{"0":""}},{"t":"case","label":"Commercial Mortgage Ins., Inc. v. Citizens National Bank","cite":"526 F. Supp. 510","y":1981,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp./526/510/","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1056","url":"https://www.law.cornell.edu/uscode/text/29/1056","subs":["(d)(1)"],"stext":{"head":"§1056. Form and payment of benefits","paras":[[0,"(a) Commencement date for payment of benefits"],[0,"Each pension plan shall provide that unless the participant otherwise elects, the payment of benefits under the plan to the participant shall begin not later than the 60th day after the latest of the close of the plan year in which—"],[1,"(1) occurs the date on which the participant attains the earlier of age 65 or the normal retirement age specified under the plan,"],[1,"(2) occurs the 10th anniversary of the year in which the participant commenced participation in the plan, or"],[1,"(3) the participant terminates his service with the employer."],[0,"In the case of a plan which provides for the payment of an early retirement benefit, such plan shall provide that a participant who satisfied the service requirements for such early retirement benefit, but separated from the service (with any nonforfeitable right to an accrued benefit) before satisfying the age requirement for such early retirement benefit, is entitled upon satisfaction of such age requirement to receive a benefit not less than the benefit to which he would be entitled at the normal retirement age, actuarially reduced under regulations prescribed by the Secretary of the Treasury."],[0,"(b) Decrease in plan benefits by reason of increases in benefit levels under Social Security Act or Railroad Retirement Act of 1937"],[0,"If—"],[1,"(1) a participant or beneficiary is receiving benefits under a pension plan, or"],[1,"(2) a participant is separated from the service and has non-forfeitable rights to benefits,"],[0,"a plan may not decrease benefits of such a participant by reason of any increase in the benefit levels payable under title II of the Social Security Act [42 U.S.C. 401 et seq.] or the Railroad Retirement Act of 1937 [45 U.S.C. 231 et seq.] or any increase in the wage base under such title II, if such increase takes place after September 2, 1974, or (if later) the earlier of the date of first entitlement of such benefits or the date of such separation."],[0,"(c) Forfeiture of accrued benefits derived from employer contributions"],[0,"No pension plan may provide that any part of a participant's accrued benefit derived from employer contributions (whether or not otherwise nonforfeitable) is forfeitable solely because of withdrawal by such participant of any amount attributable to the benefit derived from contributions made by such participant. The preceding sentence shall not apply (1) to the accrued benefit of any participant unless, at the time of such withdrawal, such participant has a nonforfeitable right to at least 50 percent of such accrued benefit, or (2) to the extent that an accrued benefit is permitted to be forfeited in accordance with section 1053(a)(3)(D)(iii) of this title."],[0,"(d) Assignment or alienation of plan benefits"],[0,"(1) Each pension plan shall provide that benefits provided under the plan may not be assigned or alienated."],[0,"(2) For the purposes of paragraph (1) of this subsection, there shall not be taken into account any voluntary and revocable assignment of not to exceed 10 percent of any benefit payment, or of any irrevocable assignment or alienation of benefits executed before September 2, 1974. The preceding sentence shall not apply to any assignment or alienation made for the purposes of defraying plan administration costs. For purposes of this paragraph a loan made to a participant or beneficiary shall not be treated as an assignment or alienation if such loan is secured by the participant's accrued non-forfeitable benefit and is exempt from the tax imposed by section 4975 of title 26 (relating to tax on prohibited transactions) by reason of section 4975(d)(1) of title 26."],[0,"(3)(A) Paragraph (1) shall apply to the creation, assignment, or recognition of a right to any benefit payable with respect to a participant pursuant to a domestic relations order, except that paragraph (1) shall not apply if the order is determined to be a qualified domestic relations order. Each pension plan shall provide for the payment of benefits in accordance with the applicable requirements of any qualified domestic relations order."],[0,"(B) For purposes of this paragraph—"],[1,"(i) the term \"qualified domestic relations order\" means a domestic relations order—"],[2,"(I) which creates or recognizes the existence of an alternate payee's right to, or assigns to an alternate payee the right to, receive all or a portion of the benefits payable with respect to a participant under a plan, and"],[2,"(II) with respect to which the requirements of subparagraphs (C) and (D) are met, and"],[1,"(ii) the term \"domestic relations order\" means any judgment, decree, or order (including approval of a property settlement agreement) which—"],[2,"(I) relates to the provision of child support, alimony payments, or marital property rights to a spouse, former spouse, child, or other dependent of a participant, and"],[2,"(II) is made pursuant to a State or Tribal domestic relations law (including a community property law)."],[1,"For purposes of clause (ii)(II), the term \"Tribal\" with respect to a domestic relations law means such a law which is issued by or under the laws of an Indian tribal government (as defined in section 7701(a)(40) of title 26), a subdivision of such an Indian tribal government, or an agency or instrumentality of either."],[0,"(C) A domestic relations order meets the requirements of this subparagraph only if such order clearly specifies—"],[1,"(i) the name and the last known mailing address (if any) of the participant and the name and mailing address of each alternate payee covered by the order,"],[1,"(ii) the amount or percentage of the participant's benefits to be paid by the plan to each such alternate payee, or the manner in which such amount or percentage is to be determined,"],[1,"(iii) the number of payments or period to which such order applies, and"],[1,"(iv) each plan to which such order applies."],[0,"(D) A domestic relations order meets the requirements of this subparagraph only if such order—"],[1,"(i) does not require a plan to provide any type or form of benefit, or any option, not otherwise provided under the plan,"],[1,"(ii) does not require the plan to provide increased benefits (determined on the basis of actuarial value), and"],[1,"(iii) does not require the payment of benefits to an alternate payee which are required to be paid to another alternate payee under another order previously determined to be a qualified domestic relations order."],[0,"(E)(i) A domestic relations order shall not be treated as failing to meet the requirements of clause (i) of subparagraph (D) solely because such order requires that payment of benefits be made to an alternate payee—"],[1,"(I) in the case of any payment before a participant has separated from service, on or after the date on which the participant attains (or would have attained) the earliest retirement age,"],[1,"(II) as if the participant had retired on the date on which such payment is to begin under such order (but taking into account only the present value of benefits actually accrued and not taking into account the present value of any employer subsidy for early retirement), and"],[1,"(III) in any form in which such benefits may be paid under the plan to the participant (other than in the form of a joint and survivor annuity with respect to the alternate payee and his or her subsequent spouse)."],[0,"For purposes of subclause (II), the interest rate assumption used in determining the present value shall be the interest rate specified in the plan or, if no rate is specified, 5 percent."],[0,"(ii) For purposes of this subparagraph, the term \"earliest retirement age\" means the earlier of—"],[1,"(I) the date on which the participant is entitled to a distribution under the plan, or"],[1,"(II) the later of the date of 1 the participant attains age 50 or the earliest date on which the participant could begin receiving benefits under the plan if the participant separated from service."],[0,"(F) To the extent provided in any qualified domestic relations order—"],[1,"(i) the former spouse of a participant shall be treated as a surviving spouse of such participant for purposes of section 1055 of this title (and any spouse of the participant shall not be treated as a spouse of the participant for such purposes), and"],[1,"(ii) if married for at least 1 year, the surviving former spouse shall be treated as meeting the requirements of section 1055(f) of this title."],[0,"(G)(i) In the case of any domestic relations order received by a plan—"],[1,"(I) the plan administrator shall promptly notify the participant and each alternate payee of the receipt of such order and the plan's procedures for determining the qualified status of domestic relations orders, and"],[1,"(II) within a reasonable period after receipt of such order, the plan administrator shall determine whether such order is a qualified domestic relations order and notify the participant and each alternate payee of such determination."],[0,"(ii) Each plan shall establish reasonable procedures to determine the qualified status of domestic relations orders and to administer distributions under such qualified orders. Such procedures—"],[1,"(I) shall be in writing,"],[1,"(II) shall provide for the notification of each person specified in a domestic relations order as entitled to payment of benefits under the plan (at the address included in the domestic relations order) of such procedures promptly upon receipt by the plan of the domestic relations order, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1056?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1056. Form and payment of benefits","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/29/401","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 1671","url":"https://www.law.cornell.edu/uscode/text/15/1671","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/29/521","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 440","url":"https://www.law.cornell.edu/uscode/text/29/440","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 464","url":"https://www.law.cornell.edu/uscode/text/29/464","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 482","url":"https://www.law.cornell.edu/uscode/text/29/482","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/29/501","subs":["(c)"],"stext":{"head":"§501. Fiduciary responsibility of officers of labor organizations","paras":[[0,"(a) Duties of officers; exculpatory provisions and resolutions void"],[0,"The officers, agents, shop stewards, and other representatives of a labor organization occupy positions of trust in relation to such organization and its members as a group. It is, therefore, the duty of each such person, taking into account the special problems and functions of a labor organization, to hold its money and property solely for the benefit of the organization and its members and to manage, invest, and expend the same in accordance with its constitution and bylaws and any resolutions of the governing bodies adopted thereunder, to refrain from dealing with such organization as an adverse party or in behalf of an adverse party in any matter connected with his duties and from holding or acquiring any pecuniary or personal interest which conflicts with the interests of such organization, and to account to the organization for any profit received by him in whatever capacity in connection with transactions conducted by him or under his direction on behalf of the organization. A general exculpatory provision in the constitution and bylaws of such a labor organization or a general exculpatory resolution of a governing body purporting to relieve any such person of liability for breach of the duties declared by this section shall be void as against public policy."],[0,"(b) Violation of duties; action by member after refusal or failure by labor organization to commence proceedings; jurisdiction; leave of court; counsel fees and expenses"],[0,"When any officer, agent, shop steward, or representative of any labor organization is alleged to have violated the duties declared in subsection (a) and the labor organization or its governing board or officers refuse or fail to sue or recover damages or secure an accounting or other appropriate relief within a reasonable time after being requested to do so by any member of the labor organization, such member may sue such officer, agent, shop steward, or representative in any district court of the United States or in any State court of competent jurisdiction to recover damages or secure an accounting or other appropriate relief for the benefit of the labor organization. No such proceeding shall be brought except upon leave of the court obtained upon verified application and for good cause shown, which application may be made ex parte. The trial judge may allot a reasonable part of the recovery in any action under this subsection to pay the fees of counsel prosecuting the suit at the instance of the member of the labor organization and to compensate such member for any expenses necessarily paid or incurred by him in connection with the litigation."],[0,"(c) Embezzlement of assets; penalty"],[0,"Any person who embezzles, steals, or unlawfully and willfully abstracts or converts to his own use, or the use of another, any of the moneys, funds, securities, property, or other assets of a labor organization of which he is an officer, or by which he is employed, directly or indirectly, shall be fined not more than $10,000 or imprisoned for not more than five years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/501?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§501. Fiduciary responsibility of officers of labor organizations","tname":"Labor","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 1676","url":"https://www.law.cornell.edu/uscode/text/15/1676","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1053","url":"https://www.law.cornell.edu/uscode/text/29/1053","subs":["(a)"],"stext":{"head":"§1053. Minimum vesting standards","paras":[[0,"(a) Nonforfeitability requirements"],[0,"Each pension plan shall provide that an employee's right to his normal retirement benefit is nonforfeitable upon the attainment of normal retirement age and in addition shall satisfy the requirements of paragraphs (1) and (2) of this subsection."],[1,"(1) A plan satisfies the requirements of this paragraph if an employee's rights in his accrued benefit derived from his own contributions are nonforfeitable."],[1,"(2)(A)(i) In the case of a defined benefit plan, a plan satisfies the requirements of this paragraph if it satisfies the requirements of clause (ii) or (iii)."],[1,"(ii) A plan satisfies the requirements of this clause if an employee who has completed at least 5 years of service has a nonforfeitable right to 100 percent of the employee's accrued benefit derived from employer contributions."],[1,"(iii) A plan satisfies the requirements of this clause if an employee has a nonforfeitable right to a percentage of the employee's accrued benefit derived from employer contributions determined under the following table:"],[1,"(B)(i) In the case of an individual account plan, a plan satisfies the requirements of this paragraph if it satisfies the requirements of clause (ii) or (iii)."],[1,"(ii) A plan satisfies the requirements of this clause if an employee who has completed at least 3 years of service has a nonforfeitable right to 100 percent of the employee's accrued benefit derived from employer contributions."],[1,"(iii) A plan satisfies the requirements of this clause if an employee has a nonforfeitable right to a percentage of the employee's accrued benefit derived from employer contributions determined under the following table:"],[1,"(3)(A) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that it is not payable if the participant dies (except in the case of a survivor annuity which is payable as provided in section 1055 of this title)."],[1,"(B) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that the payment of benefits is suspended for such period as the employee is employed, subsequent to the commencement of payment of such benefits—"],[2,"(i) in the case of a plan other than a multiemployer plan, by an employer who maintains the plan under which such benefits were being paid; and"],[2,"(ii) in the case of a multiemployer plan, in the same industry, in the same trade or craft, and the same geographic area covered by the plan, as when such benefits commenced."],[1,"The Secretary shall prescribe such regulations as may be necessary to carry out the purposes of this subparagraph, including regulations with respect to the meaning of the term \"employed\"."],[1,"(C) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because plan amendments may be given retroactive application as provided in section 1082(d)(2) of this title."],[1,"(D)(i) A right to an accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that, in the case of a participant who does not have a nonforfeitable right to at least 50 percent of his accrued benefit derived from employer contributions, such accrued benefit may be forfeited on account of the withdrawal by the participant of any amount attributable to the benefit derived from mandatory contributions (as defined in the last sentence of section 1054(c)(2)(C) of this title) made by such participant."],[1,"(ii) Clause (i) shall not apply to a plan unless the plan provides that any accrued benefit forfeited under a plan provision described in such clause shall be restored upon repayment by the participant of the full amount of the withdrawal described in such clause plus, in the case of a defined benefit plan, interest. Such interest shall be computed on such amount at the rate determined for purposes of section 1054(c)(2)(C) of this title (if such subsection applies) on the date of such repayment (computed annually from the date of such withdrawal). The plan provision required under this clause may provide that such repayment must be made (I) in the case of a withdrawal on account of separation from service, before the earlier of 5 years after the first date on which the participant is subsequently re-employed by the employer, or the close of the first period of 5 consecutive 1-year breaks in service commencing after the withdrawal; or (II) in the case of any other withdrawal, 5 years after the date of the withdrawal."],[1,"(iii) In the case of accrued benefits derived from employer contributions which accrued before September 2, 1974, a right to such accrued benefit derived from employer contributions shall not be treated as forfeitable solely because the plan provides that an amount of such accrued benefit may be forfeited on account of the withdrawal by the participant of an amount attributable to the benefit derived from mandatory contributions, made by such participant before September 2, 1974, if such amount forfeited is proportional to such amount withdrawn. This clause shall not apply to any plan to which any mandatory contribution is made after September 2, 1974. The Secretary of the Treasury shall prescribe such regulations as may be necessary to carry out the purposes of this clause."],[1,"(iv) For purposes of this subparagraph, in the case of any class-year plan, a withdrawal of employee contributions shall be treated as a withdrawal of such contributions on a plan year by plan year basis in succeeding order of time."],[1,"(v) Cross reference.—"],[2,"For nonforfeitability where the employee has a nonforfeitable right to at least 50 percent of his accrued benefit, see section 1056(c) of this title."],[1,"(E)(i) A right to an accrued benefit derived from employer contributions under a multiemployer plan shall not be treated as forfeitable solely because the plan provides that benefits accrued as a result of service with the participant's employer before the employer had an obligation to contribute under the plan may not be payable if the employer ceases contributions to the multiemployer plan."],[1,"(ii) A participant's right to an accrued benefit derived from employer contributions under a multiemployer plan shall not be treated as forfeitable solely because—"],[2,"(I) the plan is amended to reduce benefits under section 1425 1 or 1441 of this title, or"],[2,"(II) benefit payments under the plan may be suspended under section 1426 or 1441 of this title."],[1,"(F) A matching contribution (within the meaning of section 401(m) of title 26) shall not be treated as forfeitable merely because such contribution is forfeitable if the contribution to which the matching contribution relates is treated as an excess contribution under section 401(k)(8)(B) of title 26, an excess deferral under section 402(g)(2)(A) of title 26, an erroneous automatic contribution under section 414(w) of title 26, or an excess aggregate contribution under section 401(m)(6)(B) of title 26."],[0,"(b) Computation of period of service"],[0,"(1) In computing the period of service under the plan for purposes of determining the nonforfeitable percentage under subsection (a)(2), all of an employee's years of service with the employer or employers maintaining the plan shall be taken into account, except that the following may be disregarded:"],[1,"(A) years of service before age 18,2"],[1,"(B) years of service during a period for which the employee declined to contribute to a plan requiring employee contributions,2"],[1,"(C) years of service with an employer during any period for which the employer did not maintain the plan or a predecessor plan, defined by the Secretary of the Treasury;"],[1,"(D) service not required to be taken into account under paragraph (3);"],[1,"(E) years of service before January 1, 1971, unless the employee has had at least 3 years of service after December 31, 1970;"],[1,"(F) years of service before this part first applies to the plan if such service would have been disregarded under the rules of the plan with regard to breaks in service, as in effect on the applicable date; and"],[1,"(G) in the case of a multiemployer plan, years of service—"],[2,"(i) with an employer after—"],[3,"(I) a complete withdrawal of such employer from the plan (within the meaning of section 1383 of this title), or"],[3,"(II) to the extent permitted by regulations prescribed by the Secretary of the Treasury, a partial withdrawal described in section 1385(b)(2)(A)(i) of this title in connection with the decertification of the collective bargaining representative; and"],[2,"(ii) with any employer under the plan after the termination date of the plan under section 1348 of this title."],[0,"(2)(A) For purposes of this section, except as provided in subparagraph (C), the term \"year of service\" means a calendar year, plan year, or other 12-consecutive month period designated by the plan (and not prohibited under regulations prescribed by the Secretary) during which the participant has completed 1,000 hours of service."],[0,"(B) For purposes of this section, the term \"hour of service\" has the meaning provided by section 1052(a)(3)(C) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1053?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1053. Minimum vesting standards","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 171","url":"https://www.law.cornell.edu/uscode/text/29/171","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 1672","url":"https://www.law.cornell.edu/uscode/text/15/1672","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)(A)"],"by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/29/1103","subs":["(c)(1)"],"by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/29/1109","subs":["(a)"],"stext":{"head":"§1109. Liability for breach of fiduciary duty","paras":[[0,"(a) Any person who is a fiduciary with respect to a plan who breaches any of the responsibilities, obligations, or duties imposed upon fiduciaries by this subchapter shall be personally liable to make good to such plan any losses to the plan resulting from each such breach, and to restore to such plan any profits of such fiduciary which have been made through use of assets of the plan by the fiduciary, and shall be subject to such other equitable or remedial relief as the court may deem appropriate, including removal of such fiduciary. A fiduciary may also be removed for a violation of section 1111 of this title."],[0,"(b) No fiduciary shall be liable with respect to a breach of fiduciary duty under this subchapter if such breach was committed before he became a fiduciary or after he ceased to be a fiduciary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1109?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1109. Liability for breach of fiduciary duty","tname":"Labor","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 1673","url":"https://www.law.cornell.edu/uscode/text/15/1673","subs":["(c)"],"stext":{"head":"§1673. Restriction on garnishment","paras":[[0,"(a) Maximum allowable garnishment"],[0,"Except as provided in subsection (b) and in section 1675 of this title, the maximum part of the aggregate disposable earnings of an individual for any workweek which is subjected to garnishment may not exceed"],[1,"(1) 25 per centum of his disposable earnings for that week, or"],[1,"(2) the amount by which his disposable earnings for that week exceed thirty times the Federal minimum hourly wage prescribed by section 206(a)(1) of title 29 in effect at the time the earnings are payable,"],[0,"whichever is less. In the case of earnings for any pay period other than a week, the Secretary of Labor shall by regulation prescribe a multiple of the Federal minimum hourly wage equivalent in effect to that set forth in paragraph (2)."],[0,"(b) Exceptions"],[0,"(1) The restrictions of subsection (a) do not apply in the case of"],[1,"(A) any order for the support of any person issued by a court of competent jurisdiction or in accordance with an administrative procedure, which is established by State law, which affords substantial due process, and which is subject to judicial review."],[1,"(B) any order of any court of the United States having jurisdiction over cases under chapter 13 of title 11."],[1,"(C) any debt due for any State or Federal tax."],[0,"(2) The maximum part of the aggregate disposable earnings of an individual for any workweek which is subject to garnishment to enforce any order for the support of any person shall not exceed—"],[1,"(A) where such individual is supporting his spouse or dependent child (other than a spouse or child with respect to whose support such order is used), 50 per centum of such individual's disposable earnings for that week; and"],[1,"(B) where such individual is not supporting such a spouse or dependent child described in clause (A), 60 per centum of such individual's disposable earnings for that week;"],[0,"except that, with respect to the disposable earnings of any individual for any workweek, the 50 per centum specified in clause (A) shall be deemed to be 55 per centum and the 60 per centum specified in clause (B) shall be deemed to be 65 per centum, if and to the extent that such earnings are subject to garnishment to enforce a support order with respect to a period which is prior to the twelve-week period which ends with the beginning of such workweek."],[0,"(c) Execution or enforcement of garnishment order or process prohibited"],[0,"No court of the United States or any State, and no State (or officer or agency thereof), may make, execute, or enforce any order or process in violation of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1673?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1673. Restriction on garnishment","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(a)(13)(B)"],"by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(14)(C)"],"by":{"0":""}},{"t":"usc","label":"18 U.S.C. § 664","url":"https://www.law.cornell.edu/uscode/text/18/664","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(d)"],"stext":{"head":"§1144. Other laws","paras":[[0,"(a) Supersedure; effective date"],[0,"Except as provided in subsection (b) of this section, the provisions of this subchapter and subchapter III shall supersede any and all State laws insofar as they may now or hereafter relate to any employee benefit plan described in section 1003(a) of this title and not exempt under section 1003(b) of this title. This section shall take effect on January 1, 1975."],[0,"(b) Construction and application"],[0,"(1) This section shall not apply with respect to any cause of action which arose, or any act or omission which occurred, before January 1, 1975."],[0,"(2)(A) Except as provided in subparagraph (B), nothing in this subchapter shall be construed to exempt or relieve any person from any law of any State which regulates insurance, banking, or securities."],[0,"(B) Neither an employee benefit plan described in section 1003(a) of this title, which is not exempt under section 1003(b) of this title (other than a plan established primarily for the purpose of providing death benefits), nor any trust established under such a plan, shall be deemed to be an insurance company or other insurer, bank, trust company, or investment company or to be engaged in the business of insurance or banking for purposes of any law of any State purporting to regulate insurance companies, insurance contracts, banks, trust companies, or investment companies."],[0,"(3) Nothing in this section shall be construed to prohibit use by the Secretary of services or facilities of a State agency as permitted under section 1136 of this title."],[0,"(4) Subsection (a) shall not apply to any generally applicable criminal law of a State."],[0,"(5)(A) Except as provided in subparagraph (B), subsection (a) shall not apply to the Hawaii Prepaid Health Care Act (Haw. Rev. Stat. §§393–1 through 393–51)."],[0,"(B) Nothing in subparagraph (A) shall be construed to exempt from subsection (a)—"],[1,"(i) any State tax law relating to employee benefit plans, or"],[1,"(ii) any amendment of the Hawaii Prepaid Health Care Act enacted after September 2, 1974, to the extent it provides for more than the effective administration of such Act as in effect on such date."],[0,"(C) Notwithstanding subparagraph (A), parts 1 and 4 of this subtitle, and the preceding sections of this part to the extent they govern matters which are governed by the provisions of such parts 1 and 4, shall supersede the Hawaii Prepaid Health Care Act (as in effect on or after January 14, 1983), but the Secretary may enter into cooperative arrangements under this paragraph and section 1136 of this title with officials of the State of Hawaii to assist them in effectuating the policies of provisions of such Act which are superseded by such parts 1 and 4 and the preceding sections of this part."],[0,"(6)(A) Notwithstanding any other provision of this section—"],[1,"(i) in the case of an employee welfare benefit plan which is a multiple employer welfare arrangement and is fully insured (or which is a multiple employer welfare arrangement subject to an exemption under subparagraph (B)), any law of any State which regulates insurance may apply to such arrangement to the extent that such law provides—"],[2,"(I) standards, requiring the maintenance of specified levels of reserves and specified levels of contributions, which any such plan, or any trust established under such a plan, must meet in order to be considered under such law able to pay benefits in full when due, and"],[2,"(II) provisions to enforce such standards, and"],[1,"(ii) in the case of any other employee welfare benefit plan which is a multiple employer welfare arrangement, in addition to this subchapter, any law of any State which regulates insurance may apply to the extent not inconsistent with the preceding sections of this subchapter."],[0,"(B) The Secretary may, under regulations which may be prescribed by the Secretary, exempt from subparagraph (A)(ii), individually or by class, multiple employer welfare arrangements which are not fully insured. Any such exemption may be granted with respect to any arrangement or class of arrangements only if such arrangement or each arrangement which is a member of such class meets the requirements of section 1002(1) and section 1003 of this title necessary to be considered an employee welfare benefit plan to which this subchapter applies."],[0,"(C) Nothing in subparagraph (A) shall affect the manner or extent to which the provisions of this subchapter apply to an employee welfare benefit plan which is not a multiple employer welfare arrangement and which is a plan, fund, or program participating in, subscribing to, or otherwise using a multiple employer welfare arrangement to fund or administer benefits to such plan's participants and beneficiaries."],[0,"(D) For purposes of this paragraph, a multiple employer welfare arrangement shall be considered fully insured only if the terms of the arrangement provide for benefits the amount of all of which the Secretary determines are guaranteed under a contract, or policy of insurance, issued by an insurance company, insurance service, or insurance organization, qualified to conduct business in a State."],[0,"(7) Subsection (a) shall not apply to qualified domestic relations orders (within the meaning of section 1056(d)(3)(B)(i) of this title), qualified medical child support orders (within the meaning of section 1169(a)(2)(A) of this title), and the provisions of law referred to in section 1169(a)(2)(B)(ii) of this title to the extent they apply to qualified medical child support orders."],[0,"(8) Subsection (a) of this section shall not be construed to preclude any State cause of action—"],[1,"(A) with respect to which the State exercises its acquired rights under section 1169(b)(3) of this title with respect to a group health plan (as defined in section 1167(1) of this title), or"],[1,"(B) for recoupment of payment with respect to items or services pursuant to a State plan for medical assistance approved under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] which would not have been payable if such acquired rights had been executed before payment with respect to such items or services by the group health plan."],[0,"(9) For additional provisions relating to group health plans, see section 1191 of this title."],[0,"(c) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"State law\" includes all laws, decisions, rules, regulations, or other State action having the effect of law, of any State. A law of the United States applicable only to the District of Columbia shall be treated as a State law rather than a law of the United States."],[1,"(2) The term \"State\" includes a State, any political subdivisions thereof, or any agency or instrumentality of either, which purports to regulate, directly or indirectly, the terms and conditions of employee benefit plans covered by this subchapter."],[0,"(d) Alteration, amendment, modification, invalidation, impairment, or supersedure of any law of the United States prohibited"],[0,"Nothing in this subchapter shall be construed to alter, amend, modify, invalidate, impair, or supersede any law of the United States (except as provided in sections 1031 and 1137(b) of this title) or any rule or regulation issued under any such law."],[0,"(e) Automatic contribution arrangements"],[0,"(1) Notwithstanding any other provision of this section, this subchapter shall supersede any law of a State which would directly or indirectly prohibit or restrict the inclusion in any plan of an automatic contribution arrangement. The Secretary may prescribe regulations which would establish minimum standards that such an arrangement would be required to satisfy in order for this subsection to apply in the case of such arrangement."],[0,"(2) For purposes of this subsection, the term \"automatic contribution arrangement\" means an arrangement—"],[1,"(A) under which a participant may elect to have the plan sponsor make payments as contributions under the plan on behalf of the participant, or to the participant directly in cash,"],[1,"(B) under which a participant is treated as having elected to have the plan sponsor make such contributions in an amount equal to a uniform percentage of compensation provided under the plan until the participant specifically elects not to have such contributions made (or specifically elects to have such contributions made at a different percentage), and"],[1,"(C) under which such contributions are invested in accordance with regulations prescribed by the Secretary under section 1104(c)(5) of this title."],[0,"(3)(A) The plan administrator of an automatic contribution arrangement shall, within a reasonable period before such plan year, provide to each participant to whom the arrangement applies for such plan year notice of the participant's rights and obligations under the arrangement which—"],[1,"(i) is sufficiently accurate and comprehensive to apprise the participant of such rights and obligations, and"],[1,"(ii) is written in a manner calculated to be understood by the average participant to whom the arrangement applies."],[0,"(B) A notice shall not be treated as meeting the requirements of subparagraph (A) with respect to a participant unless—"],[1,"(i) the notice includes an explanation of the participant's right under the arrangement not to have elective contributions made on the participant's behalf (or to elect to have such contributions made at a different percentage),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1144?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1144. Other laws","tname":"Labor","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/29/523","subs":["(a)"],"stext":{"head":"§523. Retention of rights under other Federal and State laws","paras":[[0,"(a) Except as explicitly provided to the contrary, nothing in this chapter shall reduce or limit the responsibilities of any labor organization or any officer, agent, shop steward, or other representative of a labor organization, or of any trust in which a labor organization is interested, under any other Federal law or under the laws of any State, and, except as explicitly provided to the contrary, nothing in this chapter shall take away any right or bar any remedy to which members of a labor organization are entitled under such other Federal law or law of any State."],[0,"(b) Nothing contained in this chapter and section 186(a)–(c) of this title shall be construed to supersede or impair or otherwise affect the provisions of the Railway Labor Act, as amended [45 U.S.C. 151 et seq.], or any of the obligations, rights, benefits, privileges, or immunities of any carrier, employee, organization, representative, or person subject thereto; nor shall anything contained in this chapter be construed to confer any rights, privileges, immunities, or defenses upon employers, or to impair or otherwise affect the rights of any person under the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/523?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§523. Retention of rights under other Federal and State laws","tname":"Labor","by":{"0":""}},{"t":"usc","label":"26 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/26/411","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"26 U.S.C. § 6334","url":"https://www.law.cornell.edu/uscode/text/26/6334","subs":["(c)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 1677","url":"https://www.law.cornell.edu/uscode/text/15/1677","subs":["(1)"],"by":{"0":""}}]};